<section class="site-page-heading"><div class="container"><p class="site-kicker">检索</p><h1>搜索内容</h1></div></section>
<div class="container py-5">
  <form method="get" action="/search" class="card p-4 mb-4" role="search">
    <div class="form-row align-items-end">
      <div class="form-group col-md-5"><label for="site-search">关键词</label><input class="form-control" id="site-search" name="keyword" maxlength="100" placeholder="输入关键词" value="<?= \FangdaysCMS\Cms\View::e($search['keyword']) ?>"></div>
      <div class="form-group col-md-3"><label for="search-field">匹配范围</label><select class="form-control" id="search-field" name="field"><?php $field_choices = array('title' => '标题', 'title|content' => '标题与正文', 'content' => '正文', 'subtitle' => '副标题', 'author' => '作者', 'source' => '来源', 'keywords' => 'SEO 关键词', 'description' => '摘要'); foreach ($search['extension_fields'] as $field) { $field_choices[$field['name']] = $field['label']; } foreach ($field_choices as $name => $label): ?><option value="<?= \FangdaysCMS\Cms\View::e($name) ?>" <?= $search['field'] === $name ? 'selected' : '' ?>><?= \FangdaysCMS\Cms\View::e($label) ?></option><?php endforeach; ?><?php if (! isset($field_choices[$search['field']])): ?><option value="<?= \FangdaysCMS\Cms\View::e($search['field']) ?>" selected>当前字段组合</option><?php endif; ?></select></div>
      <div class="form-group col-md-4"><label for="search-category">栏目</label><select class="form-control" id="search-category" name="scode"><option value="">全部栏目</option><?php foreach ($search_categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= $search['scode'] === (string) $category['id'] ? 'selected' : '' ?>><?= \FangdaysCMS\Cms\View::e(str_repeat('— ', (int) $category['depth']) . $category['name']) ?></option><?php endforeach; ?><?php if ($search['scode'] !== '' && str_contains($search['scode'], ',')): ?><option value="<?= \FangdaysCMS\Cms\View::e($search['scode']) ?>" selected>当前栏目组合</option><?php endif; ?></select></div>
    </div>
    <details class="mb-3" <?= $search['conditions'] ? 'open' : '' ?>><summary>更多搜索条件</summary><div class="form-row mt-3">
      <div class="form-group col-md-4"><label for="search-title">标题包含</label><input class="form-control" id="search-title" name="title" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['title'] ?? '') ?>"></div>
      <div class="form-group col-md-4"><label for="search-content">正文包含</label><input class="form-control" id="search-content" name="content" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['content'] ?? '') ?>"></div>
      <div class="form-group col-md-4"><label for="search-author">作者包含</label><input class="form-control" id="search-author" name="author" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['author'] ?? '') ?>"></div>
      <div class="form-group col-md-4"><label for="search-subtitle">副标题包含</label><input class="form-control" id="search-subtitle" name="subtitle" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['subtitle'] ?? '') ?>"></div>
      <div class="form-group col-md-4"><label for="search-source">来源包含</label><input class="form-control" id="search-source" name="source" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['source'] ?? '') ?>"></div>
      <div class="form-group col-md-4"><label for="search-keywords">SEO 关键词包含</label><input class="form-control" id="search-keywords" name="keywords" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['keywords'] ?? '') ?>"></div>
      <div class="form-group col-md-4"><label for="search-description">摘要包含</label><input class="form-control" id="search-description" name="description" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions']['description'] ?? '') ?>"></div>
      <?php foreach ($search['extension_fields'] as $field): ?><div class="form-group col-md-4"><label for="search-ext-<?= \FangdaysCMS\Cms\View::e($field['name']) ?>"><?= \FangdaysCMS\Cms\View::e($field['label']) ?></label><input class="form-control" id="search-ext-<?= \FangdaysCMS\Cms\View::e($field['name']) ?>" name="<?= \FangdaysCMS\Cms\View::e($field['name']) ?>" maxlength="100" value="<?= \FangdaysCMS\Cms\View::e($search['conditions'][$field['name']] ?? '') ?>"></div><?php endforeach; ?>
    </div></details>
    <button class="btn btn-success align-self-start" type="submit">搜索</button>
  </form>
  <?php if ($search['invalid']): ?><p class="alert alert-warning">搜索条件无效，请检查关键词、字段或栏目。</p><?php endif; ?>
  <?php if ($search['active']): ?><h2 class="h4 mb-3">搜索结果</h2><div class="row"><?php foreach ($posts as $post): ?><div class="col-md-6 mb-3"><article class="card site-card"><div class="card-body"><h3 class="h5 mb-0"><a href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::postLink($post)) ?>"<?= $post['title_color'] !== '' ? ' style="color:' . \FangdaysCMS\Cms\View::e($post['title_color']) . '"' : '' ?>><?= \FangdaysCMS\Cms\View::e($post['title']) ?></a></h3><?php if ($post['subtitle'] !== ''): ?><p class="small mb-0"><?= \FangdaysCMS\Cms\View::e($post['subtitle']) ?></p><?php endif; ?></div></article></div><?php endforeach; ?><?php if (! $posts && ! $search['invalid']): ?><p class="col-12 text-muted">没有找到可阅读的文章。</p><?php endif; ?></div><?php endif; ?>
  <?= \FangdaysCMS\Cms\View::pagination($page, $total_pages, '/search', $search['params']) ?>
</div>
